SELECT SUM(order_count_feb) AS total_feb FROM (
SELECT COUNT(*) AS order_count_feb FROM main.orders o WHERE o.order_total > 0 AND o.ordered_at >= '2025-02-01' AND o.ordered_at < '2025-03-01'
) t

SELECT SUM(order_count_mar) AS total_mar FROM (
SELECT COUNT(*) AS order_count_mar FROM main.orders o WHERE o.order_total > 0 AND o.ordered_at >= '2025-03-01' AND o.ordered_at < '2025-04-01'
) t
